const [, , tool, argsJson = "{}"] = process.argv;
const client = new Client({ name: "done9-maria", version: "1.0.0" });
const transport = new StreamableHTTPClientTransport(new URL("http://localhost:8810/mcp"), {
  requestInit: { headers: { Authorization: `Bearer ${tok}` } },
});
try {
  await client.connect(transport);
  const r = await client.callTool({ name: tool, arguments: JSON.parse(argsJson) });
  const text = (r.content || []).map((c) => c.text ?? JSON.stringify(c)).join("\n");
  console.log(r.isError ? "ERROR " + text : text);
} catch (e) {
  console.log("MCP_FAIL " + (e && e.message));
} finally {
  await client.close().catch(() => {});
}
EOF
